<?php
namespace AutoDealership\Portal;
use AutoDealership\Database\Schema;
use AutoDealership\Security\BranchScope;
defined('ABSPATH') || exit;

final class PortalOperations {
	public static function boot():void {
		add_action('admin_post_adc_portal_operations',array(self::class,'submit'));
		add_action('init',static function(){if('1'===get_option('adc_customer_document_roles')){return;}$definitions=(array)get_option('adc_role_definitions',array());foreach(array('administrator','dealership_general_manager','dealership_finance','dealership_sales_manager') as $slug){$role=get_role($slug);if($role&&('administrator'===$slug||!isset($definitions[$slug]))&&!array_key_exists('adc_publish_customer_documents',$role->capabilities)){$role->add_cap('adc_publish_customer_documents');}}update_option('adc_customer_document_roles','1',false);},36);
	}
	/** Explicit administrator action only. Existing branch records are reused, never replaced. */
	public static function prepare(bool $demo=false) {
		global $wpdb;if(!current_user_can('manage_options')||!Schema::is_ready()){return PortalAccess::error('adc_portal_forbidden',403);}
		$lock='adc_chat_setup_'.substr(hash('sha256',$wpdb->prefix),0,20);if('1'!==(string)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,0)',$lock))){return PortalAccess::error('adc_portal_stale',409);}
		try{$mapping=(array)get_option('adc_chat_branch_mapping',array());foreach(\AutoDealership\Core\BranchLocations::all() as $branch){if(empty($branch['active'])){continue;}$key=(string)$branch['id'];$id=(int)($mapping[$key]??0);$code='WEB_'.strtoupper(substr(hash('sha256',$key),0,12));
			if(!$id){$id=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.Schema::table('branches').' WHERE code=%s OR name=%s ORDER BY code=%s DESC LIMIT 1',$code,$branch['name_ar'],$code));}
			if(!$id){$created=\AutoDealership\Branches\BranchService::create(array('code'=>$code,'name'=>$branch['name_ar'],'address'=>$branch['address_ar']??''));if(is_wp_error($created)){return $created;}$id=(int)$created['id'];}
			if(!BranchScope::is_active($id)){continue;}$mapping[$key]=$id;update_option('adc_chat_branch_mapping',$mapping,false);
			if($demo){for($index=1;$index<=2;$index++){$login='demo_chat_'.$id.'_'.$index;$slot=$key.':'.$index;$matches=get_users(array('meta_key'=>'adc_demo_chat_slot','meta_value'=>$slot,'number'=>1));$existing=$matches?$matches[0]:get_user_by('login',$login);if($existing&&'1'!==get_user_meta($existing->ID,'adc_demo_chat_staff',true)){return PortalAccess::error('adc_portal_stale',409);}
				if(!$existing){$uid=wp_insert_user(array('user_login'=>$login,'user_pass'=>wp_generate_password(48,true,true),'user_email'=>$login.'@example.invalid','display_name'=>sprintf(PortalAccess::t('مستشار تجريبي %d — %s','Demo adviser %d — %s'),$index,$branch['name_ar']),'role'=>'dealership_chat_adviser'));if(is_wp_error($uid)){return $uid;}update_user_meta($uid,'adc_demo_chat_staff','1');update_user_meta($uid,'adc_chat_available','0');}else{$uid=$existing->ID;}
				update_user_meta((int)$uid,'adc_demo_chat_slot',$slot);$result=\AutoDealership\Core\ConfigurationService::assign_branches((int)$uid,$id,array($id),'Prepare demo branch chat staff');if(is_wp_error($result)){return $result;}
			}}
		}BranchScope::clear_cache();PortalAccess::audit('operations_prepared','portal_settings',0,array('branches'=>count($mapping),'demo'=>$demo));return array('branches'=>$mapping);
		}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}
	}
	public static function form(string $op,array $fields=array()):void {echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('adc_portal_operations');foreach(array_merge(array('action'=>'adc_portal_operations','operation'=>$op,'lang'=>PortalAccess::language()),$fields) as $key=>$value){echo '<input type="hidden" name="'.esc_attr($key).'" value="'.esc_attr((string)$value).'">';}}
	public static function mapping_form():void {
		$mapping=(array)get_option('adc_chat_branch_mapping',array());self::form('mapping');echo '<h3>'.esc_html(PortalAccess::t('ربط الفروع الموجودة','Link existing branches')).'</h3><p>'.esc_html(PortalAccess::t('اختر الفرع التشغيلي المقابل لكل فرع في صفحة التواصل قبل التجهيز، أو اتركه لإنشاء فرع جديد.','Before setup, select the matching operational branch for each contact location, or leave it to create a new branch.')).'</p>';foreach(\AutoDealership\Core\BranchLocations::all() as $location){if(empty($location['active'])){continue;}echo '<label>'.esc_html(PortalAccess::t($location['name_ar'],$location['name_en'])).'<select name="mapping['.esc_attr($location['id']).']"><option value="0">'.esc_html(PortalAccess::t('إنشاء عند التجهيز','Create during setup')).'</option>';foreach(\AutoDealership\Branches\BranchService::public_list() as $branch){echo '<option value="'.(int)$branch['id'].'" '.selected($mapping[$location['id']]??0,$branch['id'],false).'>'.esc_html($branch['name'].' · '.$branch['code']).'</option>';}echo '</select></label>';}PortalView::button('حفظ ربط الفروع','Save branch links','is-secondary');echo '</form>';
	}
	public static function mapping($input) {
		if(!current_user_can('manage_options')||!is_array($input)||count($input)>50){return PortalAccess::error('adc_portal_forbidden',403);}$ids=array_column(\AutoDealership\Core\BranchLocations::all(),'id');$mapping=array();foreach($input as $key=>$value){if(!in_array($key,$ids,true)||!is_scalar($value)){return PortalAccess::error('adc_portal_input');}$branch=absint($value);if($branch&&(!BranchScope::is_active($branch)||in_array($branch,$mapping,true))){return PortalAccess::error('adc_portal_input');}if($branch){$mapping[$key]=$branch;}}
		if(!\AutoDealership\Database\Transaction::begin()){return PortalAccess::error();}update_option('adc_chat_branch_mapping',$mapping,false);if(!\AutoDealership\Database\Transaction::commit(static fn()=>PortalAccess::audit('branch_links_saved','portal_settings',0,array('count'=>count($mapping))))){wp_cache_delete('adc_chat_branch_mapping','options');wp_cache_delete('alloptions','options');return PortalAccess::error();}return true;
	}
	public static function render():void {
		if(!current_user_can('manage_options')&&!current_user_can('adc_publish_customer_documents')){wp_die('Forbidden','',array('response'=>403));}
		echo '<div class="wrap adc-portal adc-p-admin"><h1>'.esc_html(PortalAccess::t('تشغيل بوابة العميل','Customer portal operations')).'</h1>';Portal::flash();
		if(current_user_can('manage_options')){
			self::mapping_form();
			echo '<section class="adc-p-card"><h2>'.esc_html(PortalAccess::t('الفروع وموظفو المحادثات','Branches & chat advisers')).'</h2><p>'.esc_html(PortalAccess::t('يربط التجهيز فروع صفحة التواصل بفروع العمليات دون تكرارها. الحسابات التجريبية غير متصلة تلقائيًا ولا تُرسل إليها رسائل. استبدل بياناتها بموظفين حقيقيين قبل الاستخدام الفعلي.','Setup links contact-page branches with operational branches without duplicating them. Demo accounts are not automatically online and receive no mail. Replace their details with real staff before operational use.')).'</p>';self::form('prepare');echo '<label><input type="checkbox" name="demo" value="1"> '.esc_html(PortalAccess::t('إضافة مستشارَين تجريبيَين لكل فرع','Add two demo advisers per branch')).'</label>';PortalView::button('تجهيز الفروع','Prepare branches');echo '</form><ul>';foreach(PortalAccess::branches() as $branch){echo '<li>'.esc_html($branch['name']).' · '.count(LiveChat::available((int)$branch['id'])).' '.esc_html(PortalAccess::t('متاح الآن','available now')).'</li>';}echo '</ul></section>';
			$users=get_users(array('capability'=>'adc_reply_conversations','number'=>200));foreach($users as $user){if(user_can($user,'manage_options')){continue;}echo '<section class="adc-p-card"><h3>'.esc_html($user->display_name).'</h3><p><code>'.esc_html($user->user_login).'</code>'.('1'===get_user_meta($user->ID,'adc_demo_chat_staff',true)?' · '.esc_html(PortalAccess::t('حساب تجريبي','Demo account')):'').'</p>';self::form('staff',array('user'=>$user->ID));PortalView::input('display_name','اسم العرض','Display name',$user->display_name,'text','required maxlength="120"');PortalView::branches(BranchScope::assigned_branch($user->ID));PortalView::button('حفظ الاسم والفرع','Save name & branch');echo '</form><a href="'.esc_url(get_edit_user_link($user->ID)).'">'.esc_html(PortalAccess::t('إدارة البريد وكلمة المرور والدور','Manage email, password and role')).'</a></section>';}
			echo '<section class="adc-p-card"><h2>'.esc_html(PortalAccess::t('سياسة تعديل المواعيد','Appointment change policy')).'</h2>';self::form('schedule');$s=self::schedule();foreach(array('start'=>['بداية ساعات الزيارة','Visit opening hour'],'end'=>['نهاية ساعات الزيارة','Visit closing hour'],'notice'=>['الحد الأدنى قبل الموعد بالساعات','Minimum notice in hours'],'days'=>['عدد الأيام المتاحة مقدمًا','Maximum days ahead']) as $key=>$labels){PortalView::input($key,$labels[0],$labels[1],(string)$s[$key],'number','required min="'.('days'===$key?'1':'0').'" max="'.('days'===$key?'180':('notice'===$key?'168':'23')).'"');}PortalView::button('حفظ سياسة المواعيد','Save appointment policy');echo '</form></section>';
		}
		self::documents();echo '</div>';
	}
	public static function schedule():array {return array_replace(array('start'=>9,'end'=>21,'notice'=>4,'days'=>90),array_intersect_key((array)get_option('adc_portal_schedule',array()),array('start'=>1,'end'=>1,'notice'=>1,'days'=>1)));}
	public static function documents():void {
		global $wpdb;echo '<section class="adc-p-card"><h2>'.esc_html(PortalAccess::t('نشر عقد أو فاتورة للعميل','Share a contract or invoice')).'</h2><p>'.esc_html(PortalAccess::t('ارفع المستند الرسمي بصيغة PDF حتى 5 ميجابايت. يُحفظ بشكل خاص ولا يظهر إلا لصاحب عملية البيع والموظف المخوّل. لا يولد النظام فاتورة ضريبية أو توقيعًا إلكترونيًا من هذا النموذج.','Upload the official PDF, up to 5 MB. It is stored privately and shared only with the sale account owner and authorized staff. This form does not generate a tax invoice or electronic signature.')).'</p>';
		CustomerJourney::form('upload',array(),true);PortalView::input('sale','رقم عملية البيع','Sale ID','','number','required min="1"');echo '<label>'.esc_html(PortalAccess::t('نوع المستند','Document type')).'<select name="kind"><option value="contract">'.esc_html(PortalAccess::t('عقد','Contract')).'</option><option value="invoice">'.esc_html(PortalAccess::t('فاتورة','Invoice')).'</option></select></label>';PortalView::input('title','العنوان الظاهر للعميل','Customer-facing title','','text','required maxlength="190"');PortalView::input('reference','الرقم المرجعي الرسمي','Official reference','','text','required maxlength="100"');echo '<label>PDF<input type="file" name="document" accept="application/pdf,.pdf" required></label>';PortalView::button('نشر المستند للعميل','Share with customer');echo '</form></section>';
		list($scope,$args)=BranchScope::predicate('q.branch_id');if(!current_user_can('manage_options')&&!current_user_can('adc_view_branch_leads')&&!current_user_can('adc_view_finance')){$scope.=' AND s.owner_user_id=%d';$args[]=get_current_user_id();}$page=max(1,min(10000,absint($_GET['portal_page']??1)));$args[]=($page-1)*20;
		$rows=$wpdb->get_results($wpdb->prepare('SELECT d.id,d.sale_id,d.title,d.status,d.reference FROM '.PortalAccess::table('documents').' d JOIN '.Schema::table('sales').' s ON s.id=d.sale_id JOIN '.Schema::table('quotations')." q ON q.id=s.quotation_id WHERE $scope ORDER BY d.id DESC LIMIT 21 OFFSET %d",$args),ARRAY_A);
		foreach(array_slice($rows?:array(),0,20) as $row){echo '<article class="adc-p-card"><h3>'.esc_html($row['title']).'</h3><p>'.esc_html('#'.$row['sale_id'].' · '.$row['reference'].' · '.('published'===$row['status']?PortalAccess::t('متاح للعميل','Shared with customer'):PortalAccess::t('تم إلغاء الإتاحة','Revoked'))).'</p>';if('published'===$row['status']){CustomerJourney::form('download',array('id'=>$row['id']));PortalView::button('تنزيل','Download','is-secondary');echo '</form>';CustomerJourney::form('revoke',array('id'=>$row['id']));PortalView::button('إلغاء إتاحة المستند','Revoke document','is-secondary');echo '</form>';}echo '</article>';}
		PortalView::pagination($page,count($rows?:array())>20,admin_url('admin.php?page=adc-portal-operations'));
	}
	public static function submit():void {
		if(!current_user_can('manage_options')){wp_die('Forbidden','',array('response'=>403));}check_admin_referer('adc_portal_operations');$op=Portal::field('operation');$result=PortalAccess::error('adc_portal_input');
		if('prepare'===$op){$result=self::prepare('1'===Portal::field('demo'));}
		elseif('mapping'===$op){$result=self::mapping(wp_unslash($_POST['mapping']??array()));}
		elseif('staff'===$op){$uid=absint(Portal::field('user'));$name=sanitize_text_field(Portal::field('display_name'));if(current_user_can('edit_user',$uid)&&user_can($uid,'adc_reply_conversations')&&!user_can($uid,'manage_options')&&$name&&mb_strlen($name)<=120){$result=\AutoDealership\Core\ConfigurationService::assign_branches($uid,absint(Portal::field('branch')),array(absint(Portal::field('branch'))),'Chat adviser assignment');if(!is_wp_error($result)){$result=wp_update_user(array('ID'=>$uid,'display_name'=>$name));}}}
		elseif('schedule'===$op){$value=array();foreach(array('start','end','notice','days') as $key){$value[$key]=absint(Portal::field($key));}if($value['start']<$value['end']&&$value['end']<=23&&$value['notice']<=168&&$value['days']>=1&&$value['days']<=180){update_option('adc_portal_schedule',$value,false);$result=PortalAccess::audit('schedule_policy_changed','portal_settings',0,$value);}}
		set_transient('adc_portal_flash_'.get_current_user_id(),array('error'=>is_wp_error($result)||false===$result,'message'=>is_wp_error($result)?$result->get_error_message():PortalAccess::t('تم حفظ إعدادات التشغيل.','Operational settings saved.')),60);wp_safe_redirect(admin_url('admin.php?page=adc-portal-operations'),303);exit;
	}
}
